// GENERATED by tools/box.mjs build. Do not edit by hand: edit box.json and rebuild.
// Mod Box contract: the $.state values of all sub-mods under "mod-box", each with its mod prefix.

// ---- settings ----

export type Tab = 'mods' | 'profiles' | 'sources' | 'diag'

/** Result of one live check: ok, a problem, or not done yet. */
export type SourcePlugin = {
  name: string
  description: string
  /** true: a mod with function hooks; false: another kind of plugin; null: remote, checked on import. */
  isMod: boolean | null
  extras: string[]
  /** The box id when already imported. */
  imported: string | null
  /** integrate | native | blocked | unsupported, or null while the plugin is remote. */
  verdict: string | null
  reasons: string[]
  /** Its parts as short lines. */
  parts: string[]
  /** name@marketplace for a native install from a Claude marketplace. */
  nativeId: string | null
  /** Its local folder, when the source has it. */
  dir: string | null
}

/** A plugin installed as itself, as `box.mjs native list` reports it. */
export type NativePlugin = {
  id: string
  version: string
  enabled: boolean
  managed: boolean
  trusted: boolean
  group: string
  tokens: string
  hasUserConfig: boolean
  errors: string[]
  changedAt: string | null
  missing: boolean
}

/** One option of a native plugin. The value of a sensitive one is never read. */
export type NativeField = {
  key: string
  type: string
  title: string
  description: string
  sensitive: boolean
  required: boolean
  options: string[] | null
  default: unknown
  set: boolean
  value: unknown
}

export type BuiltinMod = {
  id: string
  name: string
  description: string
  enabled: boolean
  isDefault: boolean
  switchable: boolean
  note: string | null
}

export type NativeInfo = {
  components: Record<string, { count: number; names: string[] }> | null
  alwaysOn: string | null
  fields: NativeField[] | null
  error?: string
}

export type Source = {
  kind: 'claude' | 'link'
  name: string
  link: string
  dir: string | null
  error?: string
  plugins: SourcePlugin[]
}

export type ImportReport = {
  ok: boolean
  title: string
  id?: string
  error?: string
  notes: string[]
}

/** Result of the update check for one mod that comes from an original repo. */
export type UpdateInfo = {
  id: string
  status: 'current' | 'update' | 'error'
  from?: string
  to?: string
  files: string[]
  error?: string
}

/** Token usage of one mod's own model calls (see hooks/usage.ts). */
export type ModUsage = {
  calls: number
  input: number
  output: number
  cacheRead: number
  cacheWrite: number
  usd: number
  unpriced: number
}

/** A hook of the box that failed, as the trace of the outermost hook saw it. */
export type HookError = {
  at: number
  event: string
  /** skipped: failed before next; kept: failed after next; expired: ran out of time; rejected. */
  outcome: string
  /** What was thrown, when the hook threw (the message is only there for hooks of the box itself). */
  message?: string
  component?: string
  requestId?: string
  /** The switched-on mods that hook this event. */
  candidates: string[]
  count: number
}

export type EnvCheck = { id: string; ok: boolean | null; text: string }

// ---- secret-guard ----

/** A find the guard stopped (or warned about); the value itself is never kept, only its hash. */
export type BlockedFind = {
  at: number
  what: string
  where: string
  /** Path relative to the project, when the find belongs to a file. */
  path: string | null
  /** sha256 of the found value, when there is one (key patterns; not for secret files). */
  hash: string | null
  stopped: boolean
}

// ---- ci-watch ----

export type CiRun = {
  /** Actions run id; 0 for a check outside GitHub Actions (no log through gh). */
  id: number
  name: string
  status: string
  conclusion: string
  url: string
}

export type CiPhase = 'warte' | 'laeuft' | 'gruen' | 'rot' | 'keine' | 'fehler'

/** The pull request being watched, when it is one. */
export type CiPr = {
  number: number
  url: string
  title: string
  /** After green: ready to merge, waiting for a review, conflicts … (empty while running). */
  merge: string
}

export type CiWatch = {
  sha: string
  branch: string
  cwd: string
  startedAt: number
  endedAt: number
  phase: CiPhase
  runs: CiRun[]
  /** On red: the first failed run or check and the end of its log. */
  failed: { id: number; name: string; url: string; log: string } | null
  message: string
  isDismissed: boolean
  pr: CiPr | null
}

// ---- sign-guard ----

export type SignFile = { path: string; ok: boolean | null; message: string }

export type SignJob = {
  /** What was built (the detected command, shortened). */
  build: string
  cwd: string
  at: number
  files: SignFile[]
  phase: 'gefunden' | 'signiert' | 'teilweise' | 'fehler'
  isDismissed: boolean
}

// ---- savvy-progress ----

export type Phase = 'plan' | 'design' | 'delegate' | 'review' | 'close'

export type PlannedTask = {
  title: string
  tier: string
  after: number[]
}

export type Flow = {
  title: string
  total: number
  done: number
  running: number
  phase: Phase
  isFinished: boolean
  tasks: PlannedTask[]
}

export type AgentStatus = 'running' | 'done' | 'failed'

export type AgentRun = {
  id: string
  agentId?: string
  type: string
  description: string
  model: string
  effort?: string
  status: AgentStatus
  startedAt: number
  endedAt?: number
  contextTokens: number
  contextMax: number
  tokens: number
  costUsd: number
  steps: number
  round: number
  /** Self-reported by the worker through the `step` tool. */
  stepDone?: number
  stepTotal?: number
  stepNote?: string
}

export type Panel = {
  isCompact: boolean
  isDoneCollapsed: boolean
  autoOpenedFor: string
}

// ---- filetree ----

export type FileNode = {
  id: string
  parent: string
  name: string
  kind: 'dir' | 'file' | 'link'
  hidden: boolean
  mtime: number
  size: number
  loaded: boolean
}

export type Branch = {
  head: string
  upstream: string
  ahead: number
  behind: number
}

export type Activity = {
  id: number
  kind: string
  label: string
  state: 'running' | 'done' | 'failed'
  detail: string
  at: number
  tone: string
  nerd: string
  plain: string
}

export type FileTree = {
  root: string
  nodes: FileNode[]
  expanded: string[]
  cursor: string
  selected: string
  query: string
  showHidden: boolean
  showSize: boolean
  dirSizes: Record<string, number>
  git: Record<string, string>
  diff: Record<string, [number, number]>
  ignored: string[]
  untrackedDirs: string[]
  top: string
  prefix: string
  branch: Branch | null
  counts: Record<string, [number, number, number]>
  flash: string[]
  flashDim: string[]
  flashOn: boolean
  flashTones: Record<string, string>
  scroll: number | null
  preview: string
  previewTop: number
}

export type Theme = {
  fg: string
  accent: string
  muted: string
  urgent: string
  selection: string
  bg: string
}

// Mod Box: the pane's tab (files or the Codebase Map's features) and the feature opened there.
export type FileView = {
  tab: 'files' | 'features'
  feature: string
}

// ---- next-steps ----

export type NextSteps = { turnId: string; items: string[] }

// ---- cache-meter ----

export type MeterInfo = {
  /** Time of the main loop's last request (ms), 0 = unknown/cold. */
  lastAt: number
  /** Share of the last turn served from the cache, in percent. */
  hit: number | null
  percent: number | null
  tokens: number | null
  window: number | null
  /** The subscription's rate-limit windows (5 hours, week), as the status line has them. */
  limits: Array<{ kind: string; percentUsed: number; resetsAt?: string }>
}

// ---- subagent-saver ----

/** How many subagents were started on the cheaper model, and the last one. */
export type SaverStats = { routed: number; last: string }

// ---- handoff ----

export type Handoff = {
  /** Path of the found or written note. */
  path: string
  /** When it was written (ms). */
  at: number
  /** The first line with content, as a preview. */
  preview: string
  /** gefunden: found at start; geschrieben: written in this session. */
  kind: 'gefunden' | 'geschrieben'
  isDismissed: boolean
}

// ---- visible-compact ----

/** Which columns the pane shows. */
/** The palette the pane draws in; plugins aren't told the app's theme. */
export type VisibleCompactTheme = 'light' | 'dark'

export type ViewMode = 'after' | 'both' | 'before'

export type Side = 'before' | 'after'

/** One piece of a message, at most CHUNK_CHARS long, cut at a paragraph break where possible. */
export type Chunk = {
  /** Index of the message in its side's transcript. */
  m: number
  role: 'user' | 'assistant'
  /** This chunk's position within the message, and how many the message has. */
  i: number
  n: number
  text: string
}

export type ModelUsageSummary = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

/** What the index keeps for each compaction; the chunks themselves live in files beside it. */
export type CompactMeta = {
  id: string
  at: number
  durationMs: number
  trigger: 'manual' | 'auto' | 'plugin'
  /** Absent for the main conversation. */
  agentId?: string
  agentLabel?: string
  instructions?: string
  tokensBefore?: number
  tokensAfter?: number
  usage?: ModelUsageSummary
  messages: Record<Side, number>
  chunks: Record<Side, number>
}

// ---- codebase-map ----

export type BlueprintStatus =
  | { kind: 'fresh'; head: string }
  | { kind: 'behind'; head: string; stamp: string; commits: number; files: number }
  | { kind: 'unknown-stamp'; head: string; stamp: string }
  | { kind: 'no-stamp'; head: string }

export type MapFeature = {
  slug: string
  name: string
  summary: string
  files: string[]
  deps: string[]
  // Pfad-Globs aus dem INDEX-Abschnitt "Zuordnung"; leer bei älteren Blueprints.
  globs: string[]
}

// Spiegelung nach Confluence (publish-on-confluence): Opt-in im INDEX-Frontmatter, Seiten-ID nach dem ersten Publish.
export type MapConfluence = { isOptedIn: boolean; pageId: string | null }

export type MapData = { features: MapFeature[]; confluence: MapConfluence }

export type MapActivity = {
  id: string
  slug: string | null
  file: string
  agentId: string | null
}

declare module 'claude-code' {
  interface PluginState {
    'mod-box': {
      // settings
      mb_tab: Tab
      mb_links: string[]
      mb_sources: Source[] | null
      mb_loadedAt: number
      mb_busy: string | null
      mb_filter: string
      mb_open: string[]
      mb_report: ImportReport | null
      mb_expanded: string[]
      mb_natives: NativePlugin[] | null
      mb_builtins: BuiltinMod[] | null
      mb_nativeInfo: Record<string, NativeInfo>
      mb_fresh: string[]
      mb_updates: UpdateInfo[] | null
      mb_usage: Record<string, ModUsage>
      mb_errors: HookError[]
      mb_envChecks: EnvCheck[] | null
      mb_validation: { ok: boolean; text: string; at: number } | null
      mb_debugLines: string[] | null
      mb_updatedAt: number
      mb_diff: { id: string; from: string; to: string; text: string } | null

      // secret-guard
      sw_blocked: BlockedFind[]
      sw_project: string[]
      sw_global: string[]

      // ci-watch
      ci_watch: CiWatch | null

      // sign-guard
      sg_job: SignJob | null; sg_busy: boolean

      // savvy-progress
      sp_flow: Flow | null
      sp_agents: AgentRun[]
      sp_panel: Panel
      sp_now: number

      // filetree
      ft_tree: FileTree
      ft_theme: Theme
      ft_activity: Activity[]
      ft_view: FileView

      // next-steps
      ns_steps: NextSteps | null; ns_active: boolean

      // cache-meter
      cm_info: MeterInfo; cm_tick: number

      // subagent-saver
      ss_stats: SaverStats

      // handoff
      ho_note: Handoff | null; ho_text: string; ho_busy: boolean

      // visible-compact
      vc_index: CompactMeta[]
      /** The compaction shown; null follows the newest. */
      vc_selected: string | null
      vc_view: ViewMode
      vc_pages: Record<Side, number>
      vc_theme: VisibleCompactTheme

      // codebase-map
      cm2_status: BlueprintStatus | null
      cm2_dismissedAt: string | null
      cm2_map: MapData | null
      cm2_selected: string | null
      cm2_active: MapActivity[]
      cm2_touched: { [slug: string]: string[] }
      cm2_unassigned: string[]
    }
  }
}
